/* ReturnOS prototype: client-only, simulated data. No real payment, courier, or seller connections. */
const STORAGE_KEY='returnos-prototype-v1';
const initialState=()=>({
  view:'overview',selectedItem:'A',simHours:6,nowTick:0,events:[],
  riskAlert:false,riskOverturned:false,copyChecks:null,eligibility:{item:'A',condition:'unopened',category:'apparel'},
  items:[
    {id:'A',seller:'Seller 1',label:'Everyday cotton shirt',symbol:'A',gross:1000,discount:100,net:900,card:500,wallet:300,voucher:100,returned:true,status:'refund_initiated',pickupAttempts:2,condition:'New at handover',handover:true,inspection:null,appeal:false,operation:{key:'ret-A-v1',providerRef:'sim-ref-0042',amount:900,cardStatus:'reversed',walletStatus:'processing',voucherStatus:'restored',sellerStatus:'pending',createdHoursAgo:6},handoverPhotos:['Customer handover photo · front','Customer handover photo · label']},
    {id:'B',seller:'Seller 2',label:'Trail sneakers',symbol:'B',gross:800,discount:80,net:720,card:400,wallet:240,voucher:80,returned:true,status:'inspection_hold',pickupAttempts:0,condition:'Seller flagged “used”',handover:true,inspection:null,appeal:false,operation:null,handoverPhotos:['Customer handover photo · sole','Customer handover photo · upper']},
    {id:'C',seller:'Seller 2',label:'Travel bottle',symbol:'C',gross:700,discount:70,net:630,card:350,wallet:210,voucher:70,returned:false,status:'delivered',pickupAttempts:0,condition:'Not returned',handover:false,inspection:null,appeal:false,operation:null,handoverPhotos:[]},
    {id:'D',seller:'Seller 3',label:'Cotton cap',symbol:'D',gross:500,discount:50,net:450,card:250,wallet:150,voucher:50,returned:false,status:'delivered',pickupAttempts:0,condition:'Not returned',handover:false,inspection:null,appeal:false,operation:null,handoverPhotos:[]}
  ]
});
let state=loadState();
const root=document.getElementById('view-root');
const titles={overview:'Overview',eligibility:'Eligibility preview',returns:'Item journeys',refunds:'Refund ledger',reconciliation:'Reconciliation',trust:'Fairness & messages',audit:'Event audit'};
function loadState(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(s&&s.items?.length===4)return s}catch{}return initialState()}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));document.getElementById('saved-state').textContent='Saved locally'}catch{document.getElementById('saved-state').textContent='Storage unavailable'} }
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN')}
function byId(id){return state.items.find(x=>x.id===id)}
function stamp(delta=0){const d=new Date(Date.now()+delta*60000);return d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}
function log(type,title,detail,owner='ReturnOS'){state.events.unshift({id:'evt-'+Math.random().toString(36).slice(2,9),type,title,detail,owner,time:stamp(state.nowTick++),simulated:true});save()}
function toast(message,kind='success'){const el=document.createElement('div');el.className='toast '+kind;el.textContent=message;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3400)}
function setView(view){if(!titles[view])return;state.view=view;document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('crumb-current').textContent=titles[view];render();window.scrollTo({top:0,behavior:'smooth'})}
function nav(){document.getElementById('side-nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});document.getElementById('reset-demo').addEventListener('click',()=>{if(confirm('Reset all local demo actions and return to the seeded scenario?')){localStorage.removeItem(STORAGE_KEY);state=initialState();log('system','Demo reset','Seeded case restored; all states are simulated.');render();toast('Demo restored to its starting scenario.')}});document.getElementById('help-button').addEventListener('click',()=>openModal('About this prototype','SIMULATION NOTICE',`<p>This is a browser-only prototype. Order values, seller responses, courier attempts, payment statuses, and reviewer actions are simulated. Nothing here sends a real payment, schedules a real pickup, or contacts a seller.</p><div class="callout info">Actions are saved in this browser using local storage. Use <b>Reset demo</b> to restore the original challenge scenario.</div>`,[{label:'Got it',style:'primary',action:closeModal}]))}
function render(){document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view));document.getElementById('crumb-current').textContent=titles[state.view];document.getElementById('nav-return-count').textContent=state.items.filter(i=>i.returned).length;const views={overview:overviewView,eligibility:eligibilityView,returns:returnsView,refunds:refundsView,reconciliation:reconciliationView,trust:trustView,audit:auditView};root.innerHTML=views[state.view]();bindViewActions();save()}
function heading(kicker,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><div class="panel-title">${title}</div>${sub?`<div class="panel-subtitle">${sub}</div>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`}
function badge(text,cls='gray'){return `<span class="status status-${cls}">${esc(text)}</span>`}
function statusText(i){if(!i.returned)return ['Delivered','gray'];if(i.status==='pickup_dispute')return ['Pickup dispute','amber'];if(i.status==='awaiting_handover')return ['Handover pending','blue'];if(i.status==='inspection_hold')return ['Inspection hold','red'];if(i.status==='inspection_rejected')return ['Review rejected','red'];if(i.status==='refund_initiated')return ['Refund initiated','blue'];if(i.status==='refund_complete')return ['Refund confirmed','green'];if(i.status==='refund_partial')return ['Partial refund','amber'];return ['Return in progress','gray']}
function itemTable(){return `<div class="table-wrap"><table class="item-table"><thead><tr><th>ITEM</th><th>SELLER</th><th>NET VALUE</th><th>RETURN JOURNEY</th><th>ITEM STATE</th></tr></thead><tbody>${state.items.map(i=>{const [st,cl]=statusText(i);return `<tr data-select="${i.id}"><td><div class="item-name"><span class="item-thumb ${i.id.toLowerCase()}">${i.id}</span><span>${esc(i.label)}<small class="seller-tag" style="display:block;margin-top:3px">Item ${i.id}</small></span></div></td><td>${esc(i.seller)}</td><td><span class="table-amount">${money(i.net)}</span></td><td>${i.returned?badge(st,cl):'<span class="seller-tag">No request</span>'}</td><td>${i.id==='A'?badge('Provider reversed','amber'):i.id==='B'&&i.status==='inspection_hold'?badge('Evidence review','red'):i.status==='refund_complete'?badge('Confirmed','green'):i.returned?badge('Active','blue'):badge('Unaffected','gray')}</td></tr>`}).join('')}</tbody></table></div><div class="item-row-detail"><span>Order discount allocated proportionally to each line</span><span>Order net <b>${money(state.items.reduce((a,i)=>a+i.net,0))}</b></span></div>`}
function recentEvents(limit=5){const events=state.events.slice(0,limit);if(!events.length)return `<div class="empty-state">No new events yet. Demo actions appear here as they happen.</div>`;return `<div class="activity-list">${events.map(e=>`<div class="activity-entry"><span class="activity-dot">•</span><div><div class="activity-title">${esc(e.title)}</div><div class="activity-time">${esc(e.time)} · ${esc(e.owner)} · ${esc(e.detail)}</div></div></div>`).join('')}</div>`}
function quickAttention(){const a=byId('A'),b=byId('B');return `<div class="attention-card"><div class="attention-top"><span>△</span> Two cases need a clear next step</div><p>Item A has two failed pickup attempts in its history. Item B is waiting on a disputed inspection decision.</p><div class="action-row"><button class="button button-small button-warning" data-action="open-item" data-item="A">Review pickup case</button><button class="button button-small button-quiet" data-action="open-item" data-item="B">Review inspection</button></div></div><div class="callout info"><b>Money status:</b> Provider “reversed” describes the provider-side record. Bank posting is not confirmed; seller status remains pending.</div>`}
function totalOperationAmount(i){return (i.operation?[i.operation]:[]).reduce((n,op)=>n+op.amount,0)}
function overviewView(){const active=state.items.filter(i=>i.returned).length,held=state.items.filter(i=>i.status==='inspection_hold'||i.status==='pickup_dispute').length,approved=state.items.reduce((n,i)=>n+totalOperationAmount(i),0);return `${heading('Order overview','One order. Separate item journeys.','Track policy, handover, evidence, and money independently for each returned item.',`<button class="button button-primary" data-action="navigate" data-view="eligibility">＋ Preview a return</button>`)}
  <div class="order-strip"><div class="order-left"><div class="order-icon">▣</div><div><div class="order-id">Demo order · #IMX-2048</div><div class="order-meta">Demo customer <b>·</b> 4 items <b>·</b> 3 sellers <b>·</b> Card + wallet + voucher</div></div><span class="demo-label">SIMULATED ORDER</span></div><div class="order-total-wrap"><div class="order-total-label">ORDER TOTAL AFTER DISCOUNT</div><div class="order-total">₹2,700.00</div></div></div>
  <div class="metric-grid"><div class="metric-card"><div class="metric-top">Items in order <span class="metric-icon">▤</span></div><div class="metric-value">04</div><div class="metric-foot">Across 3 simulated sellers</div></div><div class="metric-card"><div class="metric-top">Return requests <span class="metric-icon teal">↩</span></div><div class="metric-value">${String(active).padStart(2,'0')}</div><div class="metric-foot">Each item tracked separately</div></div><div class="metric-card"><div class="metric-top">Needs review <span class="metric-icon amber">!</span></div><div class="metric-value">${String(held).padStart(2,'0')}</div><div class="metric-foot">Pickup evidence + inspection</div></div><div class="metric-card"><div class="metric-top">Refund operations <span class="metric-icon purple">₹</span></div><div class="metric-value">${money(approved)}</div><div class="metric-foot">Initiated or under review · simulated</div></div></div>
  <div class="overview-grid">${panel('Order items','Select any row to inspect its independent history.',itemTable(),`<button class="text-link" data-action="navigate" data-view="returns">Open item journeys →</button>`)}
  <div>${panel('Needs attention','Current simulated recovery actions.',quickAttention())}<div style="height:12px"></div>${panel('Latest case activity','Auditable events from this browser session.',recentEvents(3),`<button class="text-link" data-action="navigate" data-view="audit">View audit trail →</button>`)}</div></div>`}
function eligibilityView(){const selected=byId(state.eligibility.item),ageDays=10,windowDays=state.eligibility.category==='apparel'?30:state.eligibility.category==='electronics'?14:0,eligible=windowDays>=ageDays&&windowDays>0&&state.eligibility.condition!=='worn';return `${heading('Customer preview','Check the rules before the request','Preview policy, expected refund, and remedy trade-offs before the customer starts a return.')}
  <div class="split-view"><div>${panel('Eligibility inputs','Policy values are illustrative and configurable.',`<div class="select-field"><label for="elig-item">Order item</label><select id="elig-item">${state.items.map(i=>`<option value="${i.id}" ${i.id===selected.id?'selected':''}>Item ${i.id} · ${esc(i.label)} · ${money(i.net)}</option>`).join('')}</select></div><div class="select-field"><label for="elig-category">Category rule</label><select id="elig-category"><option value="apparel" ${state.eligibility.category==='apparel'?'selected':''}>Apparel · 30-day demo window</option><option value="electronics" ${state.eligibility.category==='electronics'?'selected':''}>Electronics · 14-day demo window</option><option value="final-sale">Final sale · no return by default</option></select></div><div class="select-field"><label for="elig-condition">Condition at handover</label><select id="elig-condition"><option value="unopened" ${state.eligibility.condition==='unopened'?'selected':''}>Unused / unopened</option><option value="opened" ${state.eligibility.condition==='opened'?'selected':''}>Opened · evidence requested</option><option value="worn" ${state.eligibility.condition==='worn'?'selected':''}>Used / worn · review needed</option></select></div><div class="policy-list"><div class="policy-row"><span class="policy-check">✓</span><div><b>Seller exception checked</b><small>Seller 1 / 2 / 3 policy version is shown in the item record. Demo exception: none.</small></div></div><div class="policy-row"><span class="policy-check">✓</span><div><b>Bundle and free-gift impact</b><small>Reprice the bundle or gift before final refund. No gift is attached in this demo order.</small></div></div><div class="policy-row"><span class="policy-check">✓</span><div><b>Promotion allocation</b><small>₹300 order discount is reallocated proportionally by item gross value.</small></div></div></div><div class="action-row" style="margin-top:14px"><button class="button button-primary" data-action="eligibility-check">Preview outcome</button><span class="demo-label">DEMO POLICY · NOT A REAL SELLER RULE</span></div>`)}
  ${eligible?`<div class="eligibility-result"><h3>Preview: eligible for return</h3><p>Item ${selected.id} is ${ageDays} days from delivery, inside the illustrative ${windowDays}-day category window, and the selected condition can proceed. Final eligibility remains subject to the configured seller policy and confirmed handover.</p></div>`:`<div class="eligibility-result warning"><h3>Preview: review required</h3><p>${windowDays===0?'This is a final-sale demo category.':`This item is ${ageDays} days from delivery; the illustrative window is ${windowDays} days.`} The selected condition may also require evidence review. Show the reason and appeal before submission.</p></div>`}
  <div style="height:12px"></div>${panel('Expected value','Net amount before any final inspection or policy adjustment.',`<div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:0"><div><div class="section-kicker">Gross</div><div class="metric-value" style="font-size:16px">${money(selected.gross)}</div></div><div><div class="section-kicker">Discount share</div><div class="metric-value" style="font-size:16px;color:#bd4c50">−${money(selected.discount)}</div></div><div><div class="section-kicker">Net preview</div><div class="metric-value" style="font-size:16px;color:#0b8f78">${money(selected.net)}</div></div></div><p class="panel-subtitle" style="margin-top:12px">Refund returns through the original instruments under this demo’s configured waterfall: voucher → wallet → card. Voucher expiry follows the applicable policy.</p>`)}
  </div><div>${panel('Compare remedies','No default nudge: choose what fits the customer.',`<div class="remedy-grid" style="grid-template-columns:1fr"><div class="remedy-card"><h3>Refund</h3><p>Return value after handover and the final decision.</p><div class="remedy-meta"><span>Timing · after approval</span><span>Price · original tender policy</span><span>Stock · not required</span></div></div><div class="remedy-card"><h3>Replacement</h3><p>Same item if inventory can be reserved.</p><div class="remedy-meta"><span>Timing · after stock reservation</span><span>Price · usually no cash difference</span><span>Stock · exact item required</span></div></div><div class="remedy-card"><h3>Exchange</h3><p>Alternate variant, priced before confirmation.</p><div class="remedy-meta"><span>Timing · after both sides are priced</span><span>Price · collect / return difference</span><span>Stock · chosen variant required</span></div></div></div>`)}<div style="height:12px"></div><div class="callout warn"><b>Important:</b> Actual category windows, seller exceptions, bundle rules, and voucher expiry are supplied by policy configuration. This prototype uses labeled demo rules.</div></div></div>`}
function itemCard(i){const [st,cl]=statusText(i);return `<article class="item-card ${state.selectedItem===i.id?'selected':''}" data-action="select-item" data-item="${i.id}"><div class="item-card-top"><div class="item-product"><span class="item-thumb ${i.id.toLowerCase()}">${i.id}</span><div><strong>Item ${i.id} · ${esc(i.label)}</strong><small>${esc(i.seller)} · ${i.returned?'Return requested':'Not returned'}</small></div></div>${badge(st,cl)}</div><div class="item-card-amount">${money(i.net)}</div><div class="item-card-caption">Net item value after allocated discount</div><div class="item-card-progress"><span style="width:${i.status==='refund_complete'?'100':i.status==='refund_initiated'?'78':i.status==='inspection_hold'?'53':i.returned?'30':'0'}%"></span></div><div class="item-card-foot"><span>${i.returned?'Policy · evidence · money':'No return journey'}</span><span>Open details →</span></div></article>`}
function flowFor(i){let steps=i.id==='A'?[['Pickup failed','2 attempts',true],['Dispute opened','Both claims logged',true],['Drop-off handover','Proof recorded',true],['Refund','Provider reversed',true]]:i.id==='B'?[['Return received','Handover captured',true],['Inspection','Used flag disputed',true],['Review','Awaiting decision',false],['Refund','On hold',false]]:[['Order delivered','No request',true],['Return','Not started',false]];return `<div class="flow-steps">${steps.map((s,j)=>`<div class="flow-step ${s[2]?'done':j===steps.findIndex(x=>!x[2])?'current':''}"><span class="flow-node">${s[2]?'✓':j+1}</span><b>${s[0]}</b><small>${s[1]}</small></div>`).join('')}</div>`}
function selectedDetail(i){if(!i)return '';const [st,cl]=statusText(i);let action='';if(i.id==='A'&&i.status==='refund_initiated')action=`<div class="action-row"><button class="button button-primary button-small" data-action="retry-refund" data-item="A">Retry refund safely</button><button class="button button-quiet button-small" data-action="open-pickup">Pickup evidence</button></div>`;else if(i.id==='B'&&i.status==='inspection_hold')action=`<div class="action-row">${i.appeal?'<button class="button button-primary button-small" data-action="review-appeal">Review appeal</button>':'<button class="button button-primary button-small" data-action="review-inspection">Review inspection</button>'}<button class="button button-quiet button-small" data-action="open-appeal">Customer appeal</button></div>`;else if(i.id==='B'&&(i.status==='refund_initiated'||i.status==='refund_partial'||i.status==='inspection_rejected'))action=`<div class="action-row">${i.operation?'<button class="button button-primary button-small" data-action="retry-refund" data-item="B">Start / retry safely</button>':''}${i.status==='inspection_rejected'?'<button class="button button-quiet button-small" data-action="open-appeal">Appeal outcome</button>':''}</div>`;else if(i.id==='A'&&i.status==='awaiting_handover')action=`<div class="action-row"><button class="button button-primary button-small" data-action="record-handover">Record simulated handover</button><button class="button button-quiet button-small" data-action="dropoff">Choose eligible drop-off</button></div>`;else if(i.id==='A'&&i.status==='pickup_dispute')action=`<div class="action-row"><button class="button button-warning button-small" data-action="reschedule">Offer reschedule</button><button class="button button-quiet button-small" data-action="dropoff">Choose drop-off</button></div>`;else action=`<div class="callout info">No return action is active. This item remains separate from returned lines.</div>`;return `<div class="panel-head"><div><div class="panel-title">Item ${i.id} · ${esc(i.label)}</div><div class="panel-subtitle">${esc(i.seller)} · ${badge(st,cl)}</div></div><span class="demo-label">SIMULATED CASE</span></div><div class="panel-body">${flowFor(i)}<div class="detail-summary"><b>Current state</b><p>${i.id==='A'?'Two pickup attempts failed with conflicting claims. Customer chose drop-off; handover proof was recorded. Refund was initiated, but provider and seller statuses differ.':i.id==='B'&&i.status==='inspection_hold'?'Seller flagged “used.” Customer handover photos are present. Refund stays on hold until SLA-bound review.':i.id==='B'&&i.inspection?`Reviewer decision: ${esc(i.inspection.outcome)}. ${esc(i.inspection.reason)}`:i.returned?`Current item state: ${esc(st)}.`:'No return requested. No action is required for this item.'}</p></div><div class="detail-meta"><div><span>Net item value</span><b>${money(i.net)}</b></div><div><span>Discount share</span><b>−${money(i.discount)}</b></div><div><span>Return reason</span><b>${i.id==='A'||i.id==='B'?'Sizing':'—'}</b></div><div><span>Handover evidence</span><b>${i.handover?'Captured · 2 photos':'Not applicable'}</b></div></div>${action}<div style="height:13px"></div>${i.id==='B'&&i.handoverPhotos.length?`<div class="callout warn"><b>Evidence conflict:</b> seller says “used”; customer handover evidence is available. Compare both sides before deciding.</div>`:''}</div>`}
function returnsView(){const chosen=byId(state.selectedItem);return `${heading('Item-level cases','Every item has its own history','Select an item to review its policy, evidence, logistics, and money state.',`<span class="demo-label">4 ITEMS · 2 RETURN REQUESTS</span>`)}<div class="detail-layout"><div><div class="item-grid">${state.items.map(itemCard).join('')}</div><div style="height:13px"></div>${panel('Recent events','A shared order can still contain separate item histories.',recentEvents(4))}</div><section class="panel">${selectedDetail(chosen)}</section></div>`}
function allocationRows(i){const amount=i.operation?totalOperationAmount(i):i.net;const voucher=Math.min(i.voucher,amount);const wallet=Math.min(i.wallet,Math.max(0,amount-voucher));const card=Math.min(i.card,Math.max(0,amount-voucher-wallet));return `<div class="money-row header"><span>REFUND DESTINATION</span><span>ORIGINAL CAP</span><span>PLANNED</span><span>STATUS</span></div><div class="money-row"><span class="source-chip"><i class="source-dot"></i>Card</span><span>${money(i.card)}</span><b>${money(card)}</b><span>${i.operation?esc(i.operation.cardStatus):'On hold'}</span></div><div class="money-row"><span class="source-chip"><i class="source-dot wallet"></i>Wallet</span><span>${money(i.wallet)}</span><b>${money(wallet)}</b><span>${i.operation?esc(i.operation.walletStatus):'On hold'}</span></div><div class="money-row"><span class="source-chip"><i class="source-dot voucher"></i>Voucher</span><span>${money(i.voucher)}</span><b>${money(voucher)}</b><span>${i.operation?esc(i.operation.voucherStatus):'On hold'}</span></div>`}
function refundsView(){const refundItems=state.items.filter(i=>i.returned);return `${heading('Refund compiler','Every rupee has an item and destination','Deterministic preview with source caps, promotion proration, and duplicate protection.')}
 <div class="callout info" style="margin-bottom:14px"><b>Configured demo waterfall:</b> voucher → wallet → card, bounded by each item’s original tender caps. Actual policies vary; voucher expiry is read from the configured rule. All values below are simulated.</div>
 <div class="split-view"><div>${refundItems.map(i=>`<section class="panel" style="margin-bottom:12px"><div class="panel-head"><div><div class="panel-title">Item ${i.id} · ${esc(i.label)} · ${money(i.net)}</div><div class="panel-subtitle">${i.operation?`Approved refund operations · ${money(totalOperationAmount(i))}`:'Preview only · blocked until inspection decision'}</div></div>${badge(i.operation?'Refund initiated':'On hold',i.operation?'blue':'amber')}</div><div class="panel-body">${allocationRows(i)}<div class="item-row-detail"><span>${i.operation?`Latest operation ${i.operation.key}`:'No payout operation created'}</span><span>Net item value ${money(i.net)}</span></div></div></section>`).join('')}
 ${panel('Original order tender','Item-level source caps sum to the paid tender.',`<div class="money-row"><span class="source-chip"><i class="source-dot"></i>Card</span><span>Original source</span><b>₹1,500</b><span class="pill-small">5/9 share</span></div><div class="money-row"><span class="source-chip"><i class="source-dot wallet"></i>Wallet</span><span>Original source</span><b>₹900</b><span class="pill-small">3/9 share</span></div><div class="money-row"><span class="source-chip"><i class="source-dot voucher"></i>Voucher</span><span>Original source</span><b>₹300</b><span class="pill-small">1/9 share</span></div>`)}
 </div><div>${panel('Allocation checks','Financial safeguards before an operation is created.',`<div class="policy-list"><div class="policy-row"><span class="policy-check">✓</span><div><b>Discount sums to ₹300</b><small>₹100 + ₹80 + ₹70 + ₹50; proportional to gross item value.</small></div></div><div class="policy-row"><span class="policy-check">✓</span><div><b>Item net sums to ₹2,700</b><small>Gross ₹3,000 less the allocated order discount.</small></div></div><div class="policy-row"><span class="policy-check">✓</span><div><b>No source cap is exceeded</b><small>Voucher, wallet, and card allocations remain inside each item’s original funding.</small></div></div><div class="policy-row"><span class="policy-check">✓</span><div><b>One stable key per logical refund</b><small>Retries reuse the same operation; no second payout is created.</small></div></div></div>`)}<div style="height:12px"></div><div class="callout warn"><b>Do not infer bank arrival:</b> “Reversed” is a provider-side state in this scenario. Only a settlement/receiving-instrument signal supports claiming funds have arrived.</div><div style="height:12px"></div>${panel('Voucher rule','Returned as voucher, not cash to the bank.',`<div class="message-preview"><b>Policy-driven destination</b><q>Voucher-funded value is restored to the voucher balance. Expiry follows the configured voucher policy; expiry is not invented in this demo.</q></div>`)}</div></div>`}
function reconcileClass(){const i=byId('A');if(i.operation?.sellerStatus==='refunded'&&i.operation.cardStatus==='settled')return 'reconciled';return state.simHours>24?'stuck':'waiting'}
function reconciliationView(){const i=byId('A'),o=i.operation,klass=reconcileClass();const badgeHTML=klass==='waiting'?badge('Waiting','amber'):klass==='stuck'?badge('Stuck','red'):badge('Reconciled','green');return `${heading('Three sources of truth','A mismatch needs meaning and an owner','Provider, seller, and platform states can update at different speeds.',`<button class="button button-quiet" data-action="advance-clock">Advance demo clock +30h</button>`)}
 <div class="callout ${klass==='stuck'?'danger':'warn'}" style="margin-bottom:14px"><b>Current classification · ${klass.toUpperCase()}</b> — ${klass==='waiting'?`The seller/provider mismatch is still inside the configured 24-hour demo window (${state.simHours}h elapsed). Next action: query the provider reference and recheck the seller ledger.`:klass==='stuck'?'The configured 24-hour demo window has passed. Keep the financial state unconfirmed, assign an operations owner, and escalate the seller/provider reconciliation.':'Provider and seller records now support the completed state.'}</div>
 <div class="recon-grid"><div class="source-status-card"><div class="source-head"><span>ReturnOS · Platform</span>${badge('Initiated','blue')}</div><p>One logical refund operation exists for Item A. Stable key prevents a duplicate effect.</p><small>Operation ${esc(o?.key||'—')} · Item A · ₹900 approved</small></div><div class="source-status-card"><div class="source-head"><span>Payment provider</span>${badge(esc(o?.cardStatus||'not sent'),'amber')}</div><p>Provider says “reversed.” This is not proof the customer’s bank has posted funds.</p><small>Reference ${esc(o?.providerRef||'not created')} · card portion ₹500</small></div><div class="source-status-card"><div class="source-head"><span>Seller ledger</span>${badge(esc(o?.sellerStatus||'pending'),o?.sellerStatus==='refunded'?'green':'amber')}</div><p>Seller view remains pending while its event/ledger catches up.</p><small>Next owner: seller operations · same operation reference</small></div></div>
 <div style="height:14px"></div><div class="split-view">${panel('Classify with configured ranges','Do not treat labels as universal.',`<div class="policy-list"><div class="policy-row"><span class="policy-check" style="background:var(--amber-bg);color:var(--amber)">…</span><div><b>WAITING</b><small>Update is inside the source-specific expected range. Schedule the next check.</small></div></div><div class="policy-row"><span class="policy-check" style="background:var(--red-bg);color:var(--red)">!</span><div><b>STUCK</b><small>Expected range expired or an actionable contradiction persists. Assign an owner and escalation.</small></div></div><div class="policy-row"><span class="policy-check">?</span><div><b>NEEDS REVIEW</b><small>Status semantics or evidence are unclear. Hold customer promise and inspect source documentation.</small></div></div></div><div class="item-row-detail"><span>Demo expected range</span><b>24 hours · ${state.simHours}h elapsed</b></div>`)}${panel('Next action by party','Each source receives one concrete reconciliation task.',`<div class="policy-list"><div class="policy-row"><span class="owner-badge">PLATFORM</span><div><b>Keep the same refund operation ID</b><small>Never create a new refund to repair a status update.</small></div></div><div class="policy-row"><span class="owner-badge">PROVIDER</span><div><b>Query provider_ref_42</b><small>Request documented reversal/settlement meaning and latest event time.</small></div></div><div class="policy-row"><span class="owner-badge">SELLER</span><div><b>Reconcile pending ledger entry</b><small>Share the same operation reference; report the seller-side event.</small></div></div></div><div class="action-row"><button class="button button-primary button-small" data-action="sync-seller">Simulate seller update</button><button class="button button-quiet button-small" data-action="check-provider">Query provider</button></div>`)}</div>`}
function trustView(){const friction=state.riskOverturned?'Standard · alert overturned':state.riskAlert?'Light check · under appeal':'Standard · no extra friction';return `${heading('Fairness guard','Frequency is context, not proof','Keep legitimate returners moving. Any extra check must be item-specific, explainable, and appealable.')}
 <div class="metric-grid"><div class="metric-card"><div class="metric-top">Returns in last 90 days <span class="metric-icon">↩</span></div><div class="metric-value">12</div><div class="metric-foot">Challenge scenario · all sizing returns</div></div><div class="metric-card"><div class="metric-top">Verified reason pattern <span class="metric-icon teal">✓</span></div><div class="metric-value" style="font-size:16px">Sizing</div><div class="metric-foot">Explainable and legitimate in this case</div></div><div class="metric-card"><div class="metric-top">Current friction <span class="metric-icon ${state.riskAlert&&!state.riskOverturned?'amber':'teal'}">♡</span></div><div class="metric-value" style="font-size:15px">${esc(friction)}</div><div class="metric-foot">Return count alone never blocks a return</div></div><div class="metric-card"><div class="metric-top">Appeal path <span class="metric-icon purple">↗</span></div><div class="metric-value" style="font-size:15px">${state.riskOverturned?'Resolved':'Available'}</div><div class="metric-foot">Reviewer reason and override are audited</div></div></div>
 <div class="panel" style="margin-bottom:14px"><div class="panel-head"><div><div class="panel-title">Proportionate friction ladder</div><div class="panel-subtitle">Escalate only when a relevant signal supports it; never use return frequency by itself.</div></div><div class="demo-label">CURRENT: ${state.riskOverturned?'STANDARD':state.riskAlert?'LIGHT CHECK':'STANDARD'}</div></div><div class="panel-body"><div class="ladder">${[['1','Standard','No additional steps'],['2','Light check','Clarify a relevant detail'],['3','Targeted review','Evidence tied to this item'],['4','Human + appeal','Reason, correction, reviewer override']].map((x,n)=>`<div class="ladder-step ${(state.riskOverturned?n===0:state.riskAlert?n===1:n===0)?'selected':''}"><span class="ladder-num">${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><div class="callout ${state.riskOverturned?'success':state.riskAlert?'warn':'info'}" style="margin-top:12px"><b>Decision explanation:</b> ${state.riskOverturned?'Frequency-only alert overturned. The reason history confirms legitimate sizing returns, so standard flow is restored.':state.riskAlert?'Demo alert used frequency alone. That is insufficient for severe friction; the customer can appeal and the fairness guard can overturn it.':'Twelve returns are all documented as legitimate sizing returns. The customer remains in the standard flow; frequency alone does not trigger friction.'}</div><div class="action-row" style="margin-top:11px">${!state.riskAlert?'<button class="button button-warning button-small" data-action="risk-trip">Simulate frequency-only alert</button>':!state.riskOverturned?'<button class="button button-primary button-small" data-action="risk-appeal">Appeal and overturn</button>':'<button class="button button-quiet button-small" data-action="risk-reset">Reset fairness scenario</button>'}</div></div></div>
 <div class="split-view">${panel('State-matched message library','Text is selected from the item’s verified state.',`<div class="select-field"><label for="message-state">Choose message state</label><select id="message-state"><option value="pickup">Pickup dispute</option><option value="provider">Provider reversed</option><option value="inspection">Inspection hold</option><option value="voucher">Voucher restored</option><option value="appeal">Appeal overturned</option></select></div><div id="message-preview">${messageHtml('pickup')}</div><div class="action-row" style="margin-top:10px"><button class="button button-primary button-small" data-action="run-copy-checks">Run wording checks</button><span class="pill-small">No message sent · preview only</span></div><div id="copy-check-result" class="panel-subtitle" style="margin-top:8px">${state.copyChecks===null?'Copy checks have not been run in this session.':`Last check: ${state.copyChecks.pass}/${state.copyChecks.total} mappings passed.`}</div>`)}${panel('Fairness measurement','Report a denominator, not just a percentage.',`<div class="message-preview"><b>False-positive rate</b><q>Legitimate heavy returners incorrectly assigned extra friction ÷ legitimate heavy returners reviewed.</q></div><p class="panel-subtitle" style="margin-top:10px">Prototype baseline: not measured. Run against a labeled test set before making a performance claim.</p>`)}</div>`}
function messageHtml(which){const map={pickup:['PICKUP DISPUTED','The courier reported that they could not reach you. You told us you were home. We logged both claims. Choose a new pickup or eligible drop-off. No refund has started.'],provider:['PROVIDER REVERSED','The provider marked the card portion reversed. This does not confirm that your bank has posted the funds. We are checking the provider reference; next update by the configured deadline.'],inspection:['INSPECTION HOLD','The seller marked this item as used. Your handover evidence is under review. We will share the decision and reason by the configured review deadline.'],voucher:['VOUCHER RESTORED','Your voucher-funded amount was restored to your voucher balance under the order policy. Voucher expiry follows the configured rule. This portion is not a bank refund.'],appeal:['APPEAL ACCEPTED','We reviewed your handover evidence and overturned the condition flag. The item refund is approved. Your refund status will update as each payment source confirms it.']};const [label,text]=map[which]||map.pickup;return `<div class="message-preview"><b>${label} · DRAFT TEMPLATE</b><q>${text}</q></div>`}
function auditView(){const filter=document.getElementById('audit-filter')?.value||'all';const ev=state.events.filter(e=>filter==='all'||e.type===filter);return `${heading('Proof-carrying history','Every action leaves an audit event','Item, actor, source, time, reason, and next action stay reviewable.',`<button class="button button-quiet" data-action="export-audit">Export audit CSV</button>`)}
 <div class="callout info" style="margin-bottom:14px"><b>Append-only in this prototype:</b> actions add events; they do not erase prior evidence. Events and actions are simulated and stored only in this browser.</div>
 ${panel('Case event log',`${state.events.length} events · newest first`,`<div class="audit-controls" style="margin-bottom:10px"><label class="sr-only" for="audit-filter">Filter audit log</label><select id="audit-filter" class="inline-filter"><option value="all">All events</option><option value="refund">Refund and money</option><option value="logistics">Pickup and handover</option><option value="inspection">Inspection and appeal</option><option value="risk">Fairness</option><option value="system">System actions</option></select><span class="pill-small">Evidence references are simulated</span></div><div class="table-wrap"><table class="event-table"><thead><tr><th>TIME</th><th>EVENT / REASON</th><th>OWNER</th><th>RECORD ID</th></tr></thead><tbody>${ev.length?ev.map(e=>`<tr><td>${esc(e.time)}</td><td><b>${esc(e.title)}</b><br>${esc(e.detail)}</td><td><span class="owner-badge">${esc(e.owner)}</span></td><td><span class="event-id">${esc(e.id)}</span></td></tr>`).join(''):`<tr><td colspan="4" class="empty-state">No events match this filter.</td></tr>`}</tbody></table></div>`,`<span class="demo-label">LOCAL AUDIT LOG</span>`)}
 <div class="callout warn" style="margin-top:12px">This local prototype is not a tamper-proof production audit store. A production system needs server-side append-only retention, access control, and evidence retention rules.</div>`}
function bindViewActions(){root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handleAction));root.querySelectorAll('[data-select]').forEach(el=>el.addEventListener('click',()=>{state.selectedItem=el.dataset.select;setView('returns')}));const ei=document.getElementById('elig-item');if(ei)ei.addEventListener('change',()=>{state.eligibility.item=ei.value;render()});const ec=document.getElementById('elig-category');if(ec)ec.addEventListener('change',()=>{state.eligibility.category=ec.value;render()});const econd=document.getElementById('elig-condition');if(econd)econd.addEventListener('change',()=>{state.eligibility.condition=econd.value;render()});const ms=document.getElementById('message-state');if(ms)ms.addEventListener('change',()=>{document.getElementById('message-preview').innerHTML=messageHtml(ms.value)});const af=document.getElementById('audit-filter');if(af)af.addEventListener('change',()=>{const v=af.value;root.innerHTML=auditView();document.getElementById('audit-filter').value=v;bindViewActions()})}
function handleAction(e){const b=e.currentTarget,action=b.dataset.action,id=b.dataset.item;switch(action){case'navigate':setView(b.dataset.view);break;case'open-item':state.selectedItem=id;setView('returns');break;case'select-item':state.selectedItem=id;render();break;case'eligibility-check':{const i=byId(state.eligibility.item);log('system','Eligibility preview generated',`Item ${i.id} · ${state.eligibility.category} · ${state.eligibility.condition}`);toast('Eligibility preview refreshed. No return request was submitted.');render();break}case'review-inspection':openInspection();break;case'review-appeal':reviewAppeal();break;case'open-appeal':openAppeal();break;case'retry-refund':retryRefund(id);break;case'open-pickup':openPickup();break;case'reschedule':reschedule();break;case'record-handover':recordHandover();break;case'dropoff':chooseDropoff();break;case'advance-clock':state.simHours+=30;log('system','Demo reconciliation clock advanced',`${state.simHours}h elapsed against a 24h expected range.`);render();toast('Simulated time advanced. Reconciliation classification updated.','warn');break;case'sync-seller':{const a=byId('A');a.operation.sellerStatus='refunded';a.operation.cardStatus='settled';a.operation.walletStatus='credited';a.status='refund_complete';log('refund','Seller/provider records reconciled','Seller confirmed and provider settlement signal simulated. Bank arrival can now be stated only for the confirmed card portion.','Seller operations');render();toast('Seller and provider records reconciled in the simulation.');break}case'check-provider':log('refund','Provider reference queried','sim-ref-0042 · latest provider event retained; bank posting still unconfirmed.','Payment operations');toast('Provider reference checked; no bank-arrival claim added.','warn');render();break;case'risk-trip':state.riskAlert=true;state.riskOverturned=false;log('risk','Frequency-only alert generated','12 returns in 90 days; demo friction set to light check pending fairness review.','Risk engine');render();toast('Demo alert raised. Frequency alone cannot impose a severe restriction.','warn');break;case'risk-appeal':state.riskOverturned=true;log('risk','Appeal accepted; alert overturned','Reason history confirms legitimate sizing returns; standard flow restored.','Human reviewer');render();toast('Alert overturned. Customer restored to standard flow.');break;case'risk-reset':state.riskAlert=false;state.riskOverturned=false;render();toast('Fairness scenario reset.');break;case'run-copy-checks':runCopyChecks();break;case'export-audit':exportAudit();break}}
function openModal(title,eyebrow,body,actions=[]){const d=document.getElementById('modal');document.getElementById('modal-title').textContent=title;document.getElementById('modal-eyebrow').textContent=eyebrow;document.getElementById('modal-body').innerHTML=body;document.getElementById('modal-actions').innerHTML=actions.map((a,i)=>`<button class="button ${a.style==='primary'?'button-primary':a.style==='warning'?'button-warning':'button-quiet'}" data-modal-action="${i}">${esc(a.label)}</button>`).join('');d.showModal();document.getElementById('modal-actions').querySelectorAll('button').forEach((x,i)=>x.addEventListener('click',actions[i].action));document.getElementById('modal-close').onclick=closeModal;d.addEventListener('click',e=>{if(e.target===d)closeModal()},{once:true})}
function closeModal(){const d=document.getElementById('modal');if(d.open)d.close()}
function openInspection(){const i=byId('B');openModal('Review Item B inspection','SIMULATED REVIEW · SLA 24H',`<p>The seller submitted a <b>“used”</b> condition flag. Customer handover evidence was captured before the seller inspection. Compare the evidence before deciding.</p><div class="recon-grid"><div class="source-status-card"><div class="source-head">Customer evidence ${badge('2 files','green')}</div><p>Photo at handover · sole condition<br>Photo at handover · upper condition</p><small>Captured at simulated handover</small></div><div class="source-status-card"><div class="source-head">Seller evidence ${badge('Flagged','red')}</div><p>Inspection status: “used”<br>Evidence detail: not supplied in this stress test</p><small>Reviewer should request evidence if absent</small></div></div><div class="detail-meta"><div><span>Item net value</span><b>₹720</b></div><div><span>Max refundable</span><b>₹720</b></div><div><span>Decision SLA</span><b>24h · simulated</b></div><div><span>Policy version</span><b>DEMO-RET-1</b></div></div><label class="upload-zone">＋ Add customer evidence from this device<input type="file" accept="image/*" id="evidence-upload" multiple></label><div id="upload-preview"></div><div class="select-field" style="margin-top:12px"><label for="review-reason">Reviewer reason</label><textarea id="review-reason" rows="2">Handover photos contradict the seller condition flag; seller evidence is insufficient in this simulated case.</textarea></div>`,[{label:'Reject · keep hold',style:'quiet',action:()=>decideInspection('rejected')},{label:'Partial · ₹360',style:'warning',action:()=>decideInspection('partial')},{label:'Approve full · ₹720',style:'primary',action:()=>decideInspection('approved')}]);document.getElementById('evidence-upload').addEventListener('change',previewUpload)}
function previewUpload(e){const files=[...e.target.files].slice(0,4);const box=document.getElementById('upload-preview');if(!files.length)return;box.innerHTML=`<div class="panel-subtitle" style="margin:9px 0">Selected locally (not uploaded): ${files.map(f=>esc(f.name)).join(', ')}</div>`;files.filter(f=>f.type.startsWith('image/')).slice(0,2).forEach(f=>{const u=URL.createObjectURL(f);box.insertAdjacentHTML('beforeend',`<img class="modal-image" src="${u}" alt="Local handover evidence preview">`)})}
function decideInspection(outcome){const i=byId('B'),reason=document.getElementById('review-reason')?.value||'Reviewer decision recorded with reason.';i.inspection={outcome,reason,at:stamp()};if(outcome==='approved'){i.status='refund_initiated';i.operation=createOperation(i,i.net)}else if(outcome==='partial'){i.status='refund_partial';i.operation=createOperation(i,360)}else{i.status='inspection_rejected'}log('inspection',`Item B decision: ${outcome}`,`${reason} · amount ${outcome==='approved'?'₹720':outcome==='partial'?'₹360':'₹0'} · appeal remains available.`,'Human reviewer');closeModal();state.selectedItem='B';setView('returns');toast(`Inspection decision recorded: ${outcome}.`)}
function openAppeal(){const i=byId('B');openModal(i.status==='inspection_hold'?'Open an inspection appeal':'Appeal this decision','CUSTOMER APPEAL',`<p>${i.status==='inspection_hold'?'Customer can challenge the “used” flag with handover photos or a written explanation. The review remains tied to Item B and the configured SLA.':`Appeal decision for Item B: <b>${esc(i.inspection?.outcome||'Not decided')}</b>.`}</p><div class="select-field"><label for="appeal-note">Customer appeal note</label><textarea id="appeal-note" rows="3">The item was unused when I handed it over. Please compare my timestamped handover photos with the inspection evidence.</textarea></div>`,[{label:'Submit appeal',style:'primary',action:()=>submitAppeal()}])}
function submitAppeal(){const i=byId('B');i.appeal=true;i.inspection={...(i.inspection||{}),outcome:'appeal_review',reason:'Customer appeal opened; decision pending human reviewer.',at:stamp()};log('inspection','Customer appeal submitted',document.getElementById('appeal-note')?.value||'Customer requested review of the item condition decision.','Customer');closeModal();if(i.status==='inspection_rejected')i.status='inspection_hold';render();toast('Appeal logged for human review.')}
function reviewAppeal(){const i=byId('B');openModal('Resolve Item B appeal','SIMULATED HUMAN REVIEW',`<p>The appeal links the customer’s handover evidence, the original inspection decision, policy version, and reviewer reason.</p><div class="callout info">Original decision: ${esc(i.inspection?.outcome||'under review')} · customer evidence remains attached · Item B only.</div><div class="select-field" style="margin-top:12px"><label for="appeal-review-reason">Reviewer outcome reason</label><textarea id="appeal-review-reason" rows="2">Handover photos contradict the seller condition flag; reverse the unsupported condition decision.</textarea></div>`,[{label:'Uphold original decision',style:'quiet',action:()=>resolveAppeal(false)},{label:'Overturn · approve refund',style:'primary',action:()=>resolveAppeal(true)}])}
function resolveAppeal(overturn){const i=byId('B'),reason=document.getElementById('appeal-review-reason')?.value||'Appeal reviewed with recorded reason.';i.inspection={...i.inspection,outcome:overturn?'appeal_overturned':'appeal_upheld',reason,at:stamp()};if(overturn){i.status='refund_initiated';i.operation=createOperation(i,i.net)}else{i.status='inspection_rejected'}log('inspection',overturn?'Appeal overturned; item refund approved':'Appeal reviewed; original decision upheld',`${reason} · customer appeal outcome recorded.`,'Human reviewer');closeModal();render();toast(overturn?'Appeal overturned. Item B refund approved in simulation.':'Appeal outcome recorded with reason.',overturn?'success':'warn')}
function createOperation(i,amount){const key=`ret-${i.id}-v1`;const existing=i.operation;if(existing&&existing.key===key){log('refund','Duplicate refund operation prevented',`Idempotency key ${key} already exists; no second payout created.`,'Idempotency guard');return existing}const op={key,providerRef:`sim-ref-${i.id}-${Math.floor(1000+Math.random()*8999)}`,amount,cardStatus:'processing',walletStatus:'processing',voucherStatus:'restored',sellerStatus:'pending',createdHoursAgo:0};log('refund','Refund operation created',`Item ${i.id} · ${money(amount)} · stable key ${key}; simulated provider ref ${op.providerRef}.`,'Refund compiler');return op}
function retryRefund(id){const i=byId(id);if(!i.operation){toast('No approved refund operation exists. Resolve the item decision first.','warn');return}const key=i.operation.key;log('refund','Refund retry requested',`same idempotency key ${key}; provider reference ${i.operation.providerRef} reused.`,'Refund service');log('refund','Duplicate payout blocked',`Idempotency guard found existing operation ${key}; one financial effect remains.`,'Idempotency guard');toast(`Retry safe: ${key} reused; duplicate payment blocked.`);render()}
function openPickup(){const i=byId('A');const actions=i.handover?[{label:'Close',style:'quiet',action:closeModal}]:[{label:'Close',style:'quiet',action:closeModal},{label:'Offer reschedule',style:'primary',action:()=>{closeModal();reschedule()}}];openModal('Item A · pickup evidence','SIMULATED LOGISTICS CASE',`<div class="event-table-wrap"><table class="event-table"><thead><tr><th>ATTEMPT</th><th>COURIER CLAIM</th><th>CUSTOMER CLAIM</th></tr></thead><tbody><tr><td>Attempt 1 · 09:10</td><td>Unreachable</td><td>Customer says they were home</td></tr><tr><td>Attempt 2 · 14:35</td><td>Unreachable</td><td>Customer says they were home</td></tr></tbody></table></div><div class="detail-summary" style="margin-top:13px"><b>Recovery outcome</b><p>Both claims were preserved. Customer selected eligible drop-off; simulated handover receipt recorded before the refund operation.</p></div><div class="callout warn">A courier code or GPS point alone is not proof the customer was absent.</div>`,actions)}
function reschedule(){const i=byId('A');i.status='awaiting_handover';i.handover=false;log('logistics','Reschedule offered to customer','Customer can choose a new pickup window or eligible drop-off.','Returns operations');state.selectedItem='A';setView('returns');toast('Reschedule option recorded. Handover remains unconfirmed.','warn')}
function recordHandover(){const i=byId('A');i.handover=true;i.status='refund_initiated';log('logistics','Item A handover proof recorded','Timestamped drop-off receipt captured; the logistics state advances.','Drop-off adapter');if(!i.operation)i.operation=createOperation(i,i.net);state.selectedItem='A';setView('returns');toast('Handover confirmed in simulation. Refund operation is now eligible.');}function chooseDropoff(){const i=byId('A');i.status='awaiting_handover';i.handover=false;openModal('Choose a drop-off option','SIMULATED RECOVERY',`<p>The customer can use a participating return point when policy allows. This selection does <b>not</b> count as handover until a receipt or scan is captured.</p><div class="callout info">Next step: customer presents the item and receives a timestamped proof-of-handover event.</div>`,[{label:'Cancel',style:'quiet',action:closeModal},{label:'Confirm drop-off choice',style:'primary',action:()=>{closeModal();log('logistics','Drop-off chosen by customer','Eligible drop-off selected; waiting for proof of handover.','Customer');render();toast('Drop-off chosen. Refund has not started.','warn')}}])}
function runCopyChecks(){const keys=['pickup','provider','inspection','voucher','appeal'];const checks=keys.map(k=>{const m=messageHtml(k);return m.includes('DRAFT TEMPLATE')&&m.length>150});const pass=checks.filter(Boolean).length;state.copyChecks={pass,total:checks.length};log('system','State-to-copy checks run',`${pass}/${checks.length} template mappings contain explicit state text.`,'Message QA');render();toast(`Message library check: ${pass}/${checks.length} state templates passed.`)}
function exportAudit(){const rows=[['id','time','type','event','detail','owner'],...state.events.map(e=>[e.id,e.time,e.type,e.title,e.detail,e.owner])];const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='returnos-simulated-audit.csv';a.click();URL.revokeObjectURL(a.href);toast('Simulated audit CSV downloaded.')}
document.getElementById('modal-close').addEventListener('click',closeModal);nav();
if(!state.events.length){
  log('system','Demo case loaded','4 items · 3 sellers · mixed tender · simulated source states.','ReturnOS');
  log('logistics','Item A · pickup attempt 1 failed','Courier marked unreachable; customer reported being home.','Courier adapter');
  log('logistics','Item A · pickup attempt 2 failed','Second unreachable code logged; customer claim retained.','Courier adapter');
  log('logistics','Item A · dispute opened','Attempt log and both claims linked to Item A.','Returns operations');
  log('logistics','Item A · drop-off handover verified','Customer-selected eligible drop-off; timestamped receipt simulated.','Drop-off adapter');
  log('refund','Item A · refund operation initiated','₹900 approved · card ₹500 · wallet ₹300 · voucher ₹100 · ret-A-v1.','Refund compiler');
  log('refund','Payment provider · reversed','sim-ref-0042 · provider-side state only; bank arrival unconfirmed.','Payment adapter');
  log('refund','Seller ledger · pending','Same operation reference; seller status is still inside expected update range.','Seller adapter');
  log('inspection','Item B · handover evidence captured','Customer photos recorded at handover before seller inspection.','Evidence service');
  log('inspection','Item B · seller flagged “used”','Condition decision disputed; item refund remains on hold.','Seller adapter');
}
